<?php
// Read-only test documents. Never insert attendance or payroll records.
require __DIR__.'/includes/access.php';$user=require_user();
require_once __DIR__.'/includes/payroll/service.php';
$db=db();header('Cache-Control: no-store, private');
if(!can($db,$user,'payroll.process.manage')||!can($db,$user,'payroll.salary.view')){http_response_code(403);exit('Payroll permission required.');}
if(!pay_ready($db)){http_response_code(404);exit('Enable payroll first.');}
$month=(new DateTimeImmutable('first day of last month'))->format('Y-m');
$company=pay_company_snapshot($db);
$employees=$db->query("SELECT u.id,u.name,e.employee_code FROM employees e JOIN users u ON u.id=e.user_id WHERE e.deleted_at IS NULL AND e.employment_status='Active' AND u.active=1 ORDER BY u.name")->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test payslips · <?=h($month)?></title><style>body{margin:0;background:#f4f5f7;color:#20252b;font:14px Arial,sans-serif}main{max-width:900px;margin:24px auto;padding:0 16px}header,article{background:white;padding:24px;border:1px solid #ddd;border-radius:10px;margin-bottom:20px}h1{font-size:22px}h2{font-size:20px}p{line-height:1.6}button,a{display:inline-block;padding:10px 16px;border-radius:6px;border:1px solid #ddd;background:white;color:#9f110c;text-decoration:none;cursor:pointer}.test-label{font-size:16px;color:#a11;font-weight:bold;border:2px solid #a11;padding:10px}.totals{display:flex;gap:24px;flex-wrap:wrap}.totals strong{display:block;font-size:22px;margin-top:6px}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}th:last-child,td:last-child{text-align:right}@media print{body{background:white}main{max-width:none;margin:0;padding:0}header,button,.missing{display:none!important}article{border:0;margin:0;border-radius:0;break-after:page;padding:15px}article:last-child{break-after:auto}body[data-print-employee] article{display:none}body[data-print-employee] article.print-selected{display:block}tr{break-inside:avoid}}</style></head><body><main>
<header><h1>Full-attendance test · <?=h(date('F Y',strtotime($month.'-01')))?></h1><p>These are test copies, not published salary slips. All days are assumed paid, with no absence or unpaid-leave deduction and no extra overtime. This is a full-month salary example, not a shift or attendance calculation.</p><p>The latest saved salary is used for each employee, even if it starts after this test month. Its actual effective date is shown below. Real attendance and payroll are unchanged.</p><a href="super-admin.php?page=payroll_payslips">Back to Payslips</a> <button onclick="document.body.removeAttribute('data-print-employee');window.print()">Print / Save all test copies as PDF</button></header>
<?php foreach($employees as $e):$q=$db->prepare('SELECT * FROM hr_salary_assignments WHERE employee_id=? ORDER BY effective_from DESC,id DESC LIMIT 1');$q->execute([$e['id']]);$assignment=$q->fetch(PDO::FETCH_ASSOC);if(!$assignment):?><p class="missing"><?=h($e['name'].' · '.$e['employee_code'])?> — assign a salary before previewing.</p><?php continue;endif;$s=json_decode($assignment['snapshot'],true);$breakup=$s['breakup']; ?>
<article><p class="test-label">TEST COPY — NOT FOR PAYMENT</p><h2><?=h($company['name'])?></h2><p>Illustrative payslip · <?=h($month)?></p><h3><?=h($e['name'].' · '.$e['employee_code'])?></h3><p>Salary structure: <?=h($s['structure_name'])?><br>Saved salary effective from: <?=h($assignment['effective_from'])?><br>Attendance assumption: full month paid · absence / unpaid leave deduction: 0</p>
<table><thead><tr><th>Component</th><th>Type</th><th>Amount (INR)</th></tr></thead><tbody><?php foreach($breakup['components'] as $c):?><tr><td><?=h($c['name']??$c['code'])?></td><td><?=h($c['category'])?></td><td><?=pay_amount((int)$c['amount'])?></td></tr><?php endforeach;?></tbody></table>
<div class="totals"><div>Gross salary<strong>₹<?=pay_amount((int)$breakup['gross'])?></strong></div><div>Configured deductions<strong>₹<?=pay_amount((int)($breakup['gross']-$breakup['net']))?></strong></div><div>Net salary estimate<strong>₹<?=pay_amount((int)$breakup['net'])?></strong></div></div><p>This preview has not recorded attendance, finalized payroll, or published a payslip to the employee.</p><button onclick="document.querySelectorAll('.print-selected').forEach(e=>e.classList.remove('print-selected'));this.closest('article').classList.add('print-selected');document.body.setAttribute('data-print-employee','1');window.print()">Print / Save this test copy</button></article>
<?php endforeach;if(!$employees):?><p>No active employees available.</p><?php endif;?></main></body></html>

